// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // The owner of C is this test contract; give it a payable fallback so
    // the ETH transferred out by withdrawAll can be received without revert.
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);

        // Fund C through its payable fallback from a fuzzed-value EOA.
        address payer = address(0xBEEF);
        vm.deal(payer, amount);
        vm.prank(payer);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertEq(address(c).balance, amount);

        uint256 balanceBefore = address(c).balance;

        // Drive c through withdrawAll (owner == this test contract).
        c.withdrawAll();

        // General rule: withdrawAll always drains the WHOLE contract balance.
        assertTrue(address(c).balance == 0 && balanceBefore > 0);
    }
}
